	@Test
	void eligibilityOnAggregateInputRemainsBelowGrouping() {
		TupleExpr source = eligibilityQuery("med", "patient");
		List<Statement> statements = medicationStatements("med");
		assertEquals(List.of(Map.of("patient", "urn:patient1", "medCount", "1")),
				normalized(evaluate(source, statements)));
		assertEquivalentAlternatives(source, statements, PackedRuleProofs.ELIGIBILITY_UNION_EXISTS, true);
	}

