	private static TupleExpr eligibilityQuery(String correlation, String groupKeys) {
		return eligibilityQuery(correlation, groupKeys, "?med");
	}

	private static TupleExpr eligibilityQuery(String correlation, String groupKeys, String countedExpression) {
		return eligibilityQuery(correlation, groupKeys, countedExpression, "med");
	}

	private static TupleExpr eligibilityQuery(String correlation, String groupKeys, String countedExpression,
			String havingVariable) {
		TupleExpr source = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, """
				SELECT %s (COUNT(DISTINCT %s) AS ?medCount) WHERE {
				  ?patient <urn:hasMedication> ?med .
				}
				%s
				HAVING (COUNT(?%s) > 0)
				""".formatted(groupKeys.isEmpty() ? "" : "?patient", countedExpression,
				groupKeys.isEmpty() ? ""
						: "GROUP BY " + Arrays.stream(groupKeys.split(" "))
								.map(name -> "?" + name)
								.reduce((left, right) -> left + " " + right)
								.orElseThrow(),
				havingVariable),
				null).getTupleExpr();
		source.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Group group) {
				TupleExpr base = group.getArg();
				StatementPattern first = new StatementPattern(Var.of(correlation), Var.of("type", RDF.TYPE),
						Var.of("eligible", iri("urn:Eligible")));
				StatementPattern second = new StatementPattern(Var.of(correlation),
						Var.of("eligibility", iri("urn:eligibleBy")), Var.of("witness"));
				if (havingVariable.equals("witness")) {
					first = new StatementPattern(Var.of(correlation),
							Var.of("firstEligibility", iri("urn:firstEligibility")), Var.of("witness"));
					second = new StatementPattern(Var.of(correlation),
							Var.of("secondEligibility", iri("urn:secondEligibility")), Var.of("witness"));
				}
				group.setArg(new Union(new Join(base.clone(), first), new Join(base.clone(), second)));
			}
		});
		return source instanceof QueryRoot root ? root.getArg().clone() : source;
	}

	private static BindingSetAssignment assignment(Set<String> names, BindingSet... rows) {
		BindingSetAssignment result = new BindingSetAssignment();
		result.setBindingNames(names);
		result.setBindingSets(List.of(rows));
		return result;
	}

	private static List<Statement> medicationStatements(String correlation) {
		return List.of(
				VF.createStatement(iri("urn:patient1"), iri("urn:hasMedication"), iri("urn:m1")),
				VF.createStatement(iri("urn:patient1"), iri("urn:hasMedication"), iri("urn:m2")),
				VF.createStatement(iri("urn:patient2"), iri("urn:hasMedication"), iri("urn:m3")),
				VF.createStatement(iri(correlation.equals("med") ? "urn:m1" : "urn:patient1"), RDF.TYPE,
						iri("urn:Eligible")));
	}

	private static TupleExpr codeTypeBranch(String type, String graph) {
		BindingSetAssignment targets = new BindingSetAssignment();
		targets.setBindingNames(Set.of("target"));
		MapBindingSet first = new MapBindingSet();
		first.setBinding("target", VF.createLiteral("A"));
		MapBindingSet second = new MapBindingSet();
		second.setBinding("target", VF.createLiteral("B"));
		targets.setBindingSets(List.of(first, second));
		StatementPattern typePattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("entity"), Var.of("rdfType", RDF.TYPE), Var.of("typeValue", iri(type)),
				Var.of("graph", iri(graph)));
		StatementPattern codePattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("entity"), Var.of("codePredicate", iri("urn:code")), Var.of("code"),
				Var.of("graph", iri(graph)));
		Join patterns = new Join(typePattern, codePattern);
		patterns.setVariableScopeChange(true);
		return new Filter(new Join(targets, patterns), new Or(
				new Compare(Var.of("code"), Var.of("target"), Compare.CompareOp.EQ),
				new Compare(Var.of("code"), new ValueConstant(VF.createLiteral("C")), Compare.CompareOp.EQ)));
	}

	private static void assertEquivalentAlternatives(TupleExpr source, List<Statement> statements, long proof,
			boolean expectRewrite) {
		List<Map<String, String>> expected = normalized(evaluate(source.clone(), statements));
		PackedPlanningResult result = PackedCascadesPlanner.optimize(source.clone(), OptimizationGoal.root());
		assertEquals(expected, normalized(evaluate(result.selectedPlan(), statements)),
				result.selectedPlan()::toString);
		PackedQuery query = PackedQueryCodec.encodeForPlanning(source.clone());
		PackedQueryView view = new PackedQueryView(query);
		int alternativeCount = 0;
		for (int id = 1; id <= query.relationCount(); id++) {
			if ((query.relRuleMask(id) & proof) != 0L
					&& query.relGroup(id) == query.relGroup(query.rootRelId())) {
				TupleExpr alternative = view.materializeRelation(id);
				assertEquals(expected, normalized(evaluate(alternative, statements)), alternative::toString);
				alternativeCount++;
			}
		}
		if (expectRewrite) {
			assertTrue(alternativeCount > 0, "Safe cases must retain the optimized alternative");
		}
	}

	private static List<Map<String, String>> normalized(List<BindingSet> rows) {
		return rows.stream().map(row -> {
			Map<String, String> result = new TreeMap<>();
			row.forEach(binding -> result.put(binding.getName(), binding.getValue().stringValue()));
			return result;
		}).sorted((left, right) -> left.toString().compareTo(right.toString())).toList();
	}

	private static List<BindingSet> evaluate(TupleExpr expression, List<Statement> statements) {
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new CloseableIteratorIteration<>(statements.stream()
						.filter(s -> subject == null || s.getSubject().equals(subject))
						.filter(s -> predicate == null || s.getPredicate().equals(predicate))
						.filter(s -> object == null || s.getObject().equals(object))
						.filter(s -> contexts.length == 0 || Arrays.stream(contexts)
								.anyMatch(context -> Objects.equals(context, s.getContext())))
						.iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(source, null);
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> result = strategy.precompile(expression)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}

	private static Statement statement(String subject, IRI predicate, Value object, String graph) {
		return VF.createStatement(iri(subject), predicate, object, iri(graph));
	}

	private static IRI iri(String value) {
		return VF.createIRI(value);
	}
